ui.header:
// Мелкие отклики интерфейса: тосты, вибрация, анимации, паузы.
// Вынесено из main.js: этим пользуются почти все экраны, и держать их
// в одном файле с версткой было неудобно.
//
// Важно: flash() раньше вызывал render() напрямую — теперь функция
// отрисовки внедряется из main.js через setRenderFn(), иначе получился бы
// циклический импорт main ⇄ ui-feedback.

constants.header:
// Флаги и словари, которые нужны сразу нескольким экранам.
// Раньше лежали вперемешку по 12 тысячам строк main.js — найти нужный
// было почти невозможно. Значения не менялись при переносе.
//
// Флаги включения (UI_MOTION, BOOT_SPLASH, NAV_WITH_ICONS и т.п.) оставлены
// намеренно: рядом с каждым в комментарии написано, что будет при false,
// и где лежит бэкап прежнего поведения.

state.header:
// Состояние приложения и тема.
//
// state — один большой объект: экраны меняют его поля (state.tab = 'home'),
// но сам объект не пересоздаётся. Поэтому его безопасно импортировать:
// все модули видят одни и те же поля.
//
// Ключи localStorage вынесены сюда же: их читают и состояние, и выбор группы.

install.header:
// Установка сайта на телефон (ярлык на экран «Домой»).
// Chrome/Android умеет показать системное окно установки, iOS — только
// инструкцию словами. Отсюда отдельный набор текстов под каждую платформу.

glue.text:
if (typeof window !== 'undefined') {
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault()
    deferredInstallPrompt = e
    installPromptReady = true
  })
  window.addEventListener('appinstalled', () => {
    deferredInstallPrompt = null
    installPromptReady = false
    state.showInstallHelp = false
    flash('Ярлык добавлен на экран')
  })
}

time.header:
// Дата, время, подписи: «сейчас идёт», «через 20 минут», границы недели,
// формат «14 ноября», сокращения ФИО и телефонов.
//
// Всё это раньше было разбросано по main.js между экранами. Одна функция
// на каждый случай — чтобы форматы не расходились между вкладками.

lightbox.header:
// Полноэкранный просмотр фото из домашки.
//
// Отдельный модуль, потому что это самый автономный кусок: он рисует
// собственный слой поверх страницы, ловит свайпы и закрывается по Esc.
// Раньше занимал 450 строк посреди main.js.

schedule.header:
// Экран «Расписание»: день, неделя, календарь на месяц и построение.
//
// Самый крупный экран приложения. Вынесен вместе с построением
// (это часть того же экрана, а не отдельная фича).
//
// Функции ядра (render, переход по вкладкам, обновление панелей) зовутся
// через мост app/hub.js — иначе получился бы циклический импорт.

admin.header:
// Админ-панель: коды доступа, доп. админы, поддержка, настройки сайта,
// группы, статистика и журнал событий.
//
// Это самая большая функция в проекте была renderAdminPanel — 1269 строк
// в одном теле. Теперь она здесь, вместе с секциями и разбором журнала.

news.header:
// Лента новостей: карточки на главной, полноэкранная читалка и компоузер.
//
// Читалка — отдельный слой с горизонтальными свайпами и автослайдом.
// Вынесена вместе с компоузером: они делят черновик state.newsDraft.

programs.header:
// Образовательные программы: список, читалка и редактор.
//
// Программы ведут старосты и админы; читалка общая для всех.
// Картинки и видео берутся из тех же файлов, что и вложения к ДЗ.

more.header:
// Экран «Профиль»: кабинет, состав группы, коды, контакты, замены
// и мелкие настройки (тема, установка, выход).
//
// Здесь же экраны «забанен» и «сайт закрыт» — они тоже про доступ.
// Таблицы ролей и подписей вынесены в constants.js.

directory.header:
// Вкладка «Справочник»: поиск преподавателя или свободной аудитории
// по дате и паре.
//
// Два режима в одном экране: по преподавателю и по аудитории. Результаты
// собираются отдельными функциями, чтобы не дублировать разметку.

navigation.header:
// Нижнее меню, пять вкладок и свайпы между ними.
//
// Все вкладки всегда в DOM (pager): свайп только двигает transform,
// ничего не пересобирая заново. Поэтому тут и переключение, и жесты, и
// сохранение прокрутки внутри панели.

pager.header:
// Пять вкладок в одном «пейджере»: все панели всегда в DOM,
// свайп только двигает transform. Здесь же сохранение прокрутки.
//
// pendingRedraw и sync* остаются в main.js — это общая машинерия
// синхронизации, её дёргают отовсюду.
